import React, { useCallback } from 'react';
import { SearchEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_MODEL_ID, VIEWPORT_LESS_TOP_HEADER } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

const BG = '#F0EEE7';
const LABEL = 'rgba(0,0,0,0.45)';

export default function SearchPage() {
  const { hiddenActions, disabledActions } = useTier();

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot Search]', formatThoughtSpotEmbedError(err), err);
  }, []);

  return (
    <div
      style={{
        height: VIEWPORT_LESS_TOP_HEADER,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: BG,
        overflow: 'hidden',
        minHeight: 0,
      }}
    >
      <div style={{ padding: '1.25rem 2rem 0.75rem', flexShrink: 0, borderBottom: '1px solid rgba(0,0,0,0.08)' }}>
        <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: '0.12em', textTransform: 'uppercase', color: LABEL, marginBottom: 4 }}>VisioLab</div>
        <h1 style={{ fontSize: 22, fontWeight: 700, color: '#0D0D0D', margin: 0, letterSpacing: '-0.03em' }}>Search</h1>
        <p style={{ fontSize: 13, color: 'rgba(17,17,17,0.50)', margin: '4px 0 0' }}>
          Search your venue data with guided tokens and filters.
        </p>
      </div>

      <div style={{ padding: '0.75rem 2rem 1.25rem', flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
        <div
          style={{
            flex: 1,
            minHeight: 0,
            backgroundColor: '#FFFFFF',
            borderRadius: 10,
            border: '1px solid rgba(0,0,0,0.07)',
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column',
            boxShadow: '0 1px 12px rgba(0,0,0,0.06)',
          }}
        >
          <SearchEmbed
            dataSource={THOUGHTSPOT_MODEL_ID}
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            onError={onError}
            style={{ width: '100%', height: '100%', flex: 1, minHeight: 0, border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
